# Let me try: find non-overlapping 2x2 squares greedily

def greedy_nonoverlapping_2x2(grid):
    """Find non-overlapping 2x2 squares greedily by left-to-right, top-to-bottom."""
    visited = set()
    squares = []
    for r in range(len(grid)-1):
        for c in range(len(grid[0])-1):
            cells = [(r,c), (r,c+1), (r+1,c), (r+1,c+1)]
            if all(
                grid[row][col] == 8 and (row, col) not in visited
                for row, col in cells
            ):
                squares.append(cells)
                visited.update(cells)
    return squares

